# English lecture content. Each section becomes one horizontal Reveal.js stack.
A='Access'; F='Files in VS Code'; C='Shell essentials'; J='Slurm jobs'; P='Software and packages'; R='Run and check'

BATCH=[
('#!/bin/bash','Use Bash to read the commands.'),
('#SBATCH --job-name=hello','Give the job a recognizable name.'),
('#SBATCH --account=YOUR_ACCOUNT','Use the Slurm account assigned to your group.'),
('#SBATCH --partition=YOUR_PARTITION','Use a partition that this account can access.'),
('#SBATCH --nodes=1','Request one compute node.'),
('#SBATCH --ntasks=1','Request one task for this program.'),
('#SBATCH --cpus-per-task=1','Reserve one CPU for that task.'),
('#SBATCH --mem=1G','Request 1 GiB of RAM per node.'),
('#SBATCH --time=00:05:00','Set a five-minute running-time limit.'),
('echo "My first HPC job"','Print a message into the job output.')]


S('Getting started on the<br>Illinois Campus Cluster',
  '<div class="cover-copy"><p class="cover-sub">A practical workflow for data analysis</p></div>'+img('cluster-photo.png','University of Illinois computing hardware','','cover-photo'),
  'Today I’ll give a brief introduction to the Illinois Campus Cluster. We’ll cover the basic skills needed to run computationally intensive analyses on HPC.',['computes'],A,'cover')

S('Prepare files on login nodes; run jobs on compute nodes',
  img('icc-overview.png','Official NCSA Campus Cluster usage overview','HPC = high-performance computing. A node is one computer. Login: prepare files. Compute: run scheduled analysis.','overview-image'),
  'HPC stands for high-performance computing. A cluster is a collection of connected computers, and a node is one of those computers. In this diagram, the connection from the laptop reaches a head node, also called a login node.\n\nThe login node is where we connect, organize files, edit scripts, and submit jobs. It is shared with other people, so substantial analysis should run on compute nodes. A job is a request to run a program with specified computing resources. The scheduler assigns those resources and starts the program when they become available.\n\nThe shared filesystem holds the project files, so both the login and compute nodes can reach them. Opening VS Code does not reserve a compute node. We first need an approved account and the details of the resources we are allowed to use.',
  ['start','jobs'],
  A,
  'image-slide')

S('Request access and confirm your allocation details',
  cols(rows([('Existing lab access','Ask your PI or technical contact which cluster group to join.'),('A new computing need','Start an Illinois Computes request.')]),table(['Detail to confirm','Used for'],[['NetID','Your login identity'],['Slurm account','The group’s assigned computing resources'],['Partition','A queue you may submit to'],['Project path','A folder where you have permission to save files']]))+'<div class="link-row"><a href="https://campuscluster.illinois.edu/new_forms/user_form.php" target="_blank">Research access request ↗</a><a href="https://computes.illinois.edu/submitrequest/" target="_blank">Illinois Computes request ↗</a></div>'+p('Before connecting: get account approval, confirm these four details, and set up Duo.','small'),
  'Access starts with the group’s principal investigator, or PI, or its technical contact. An investor group is a lab or organization that has arranged cluster resources. If the group already has access, ask which group to join. A new computing need can begin through Illinois Computes. Submitting a form starts the request; the account must be approved and set up before login works.\n\nThere are four details to keep. Your NetID identifies you. The Slurm account tells the scheduler which group’s assigned computing resources the job may use; it is different from your NetID. Slurm is the software that schedules jobs. A partition is a queue of eligible computing resources. The project path tells you where your files can be stored.\n\nAsk the contact for a valid account and partition pair and a folder you can write to. Also confirm Duo is ready. Uppercase text such as YOUR_NETID is a placeholder: replace it with your actual value before running a command.',['access','routes','request','jobs'],A)

S('The first SSH login',
  code('ssh YOUR_NETID@cc-login.campuscluster.illinois.edu','On your laptop: open Terminal (macOS) or PowerShell (Windows)')+p('<code>ssh</code> starts the connection · before <code>@</code>: your user name · after <code>@</code>: the cluster address','small')+cols(rows([('1 · Run the command','Replace YOUR_NETID, then press Enter.'),('2 · Password','Type your NetID password and press Enter; typing stays hidden.'),('3 · Duo','Follow the prompt and approve the authentication request.')]),img('icc-login.png','Official example of a successful ICC login','A welcome message and cluster command prompt confirm login. Screenshot dates and quotas are historical.','login-image')),
  'This command runs on the laptop. Open Terminal on macOS or PowerShell on Windows. If ssh is unavailable on Windows, enable the OpenSSH Client first. The word ssh starts the remote connection. Before the at sign is your NetID; after it is the cluster address. Replace YOUR_NETID, keep the hostname as shown, and press Enter.\n\nOn a first connection, SSH may ask you to confirm the server’s identity. Check the host fingerprint with institutional guidance or support before accepting. An unexpected changed-host warning needs investigation. Then enter the NetID password. Nothing appears while it is typed; that is normal. Complete the Duo step on the registered device. ICC uses password and Duo authentication, not user-created SSH keys.\n\nA welcome message and remote command prompt indicate success. A prompt is the text showing that the shell is ready for a command. Commands entered there now run on the cluster. The screenshot’s dates and quota values are historical. VS Code opens its own connection, so exit can close this initial test without deleting files. Next, we will introduce VS Code before using it to connect.',['access'],A,'compact')

S('VS Code is an editor for code and project files',
  '<div class="vscode-intro-grid">'+img('vscode-interface.png','Official Microsoft VS Code screenshot showing the Explorer, code editors, and terminal','Microsoft example: B = files, C = editor, D = terminal panel.','vscode-interface-image')+'<div class="vscode-intro-copy">'+p('Visual Studio Code (VS Code) is Microsoft’s code editor for working with scripts and project files.')+rows([('B · Explorer','Browse files and folders in the left sidebar.'),('C · Editor','Read and edit scripts in the main area.'),('D · Terminal','Enter commands in the bottom panel.')])+'</div></div>',
  'Visual Studio Code, usually shortened to VS Code, is Microsoft’s editor for code and project files. It puts file browsing, editing, and a terminal in one desktop window. A script is simply a text file containing instructions for a program to run.\n\nThis is an official Microsoft example, so its filenames and code are not part of our cluster project. The area marked B currently shows Explorer, which lists files and folders. The areas marked C show the contents of open files. The panel marked D currently contains the terminal, where commands can be entered. That panel can also show other views.\n\nThese are the three areas we will use: Explorer for files, the editor for scripts, and the terminal for commands. Next, we will see how this window connects to files on the cluster.',['vscode_ui'],F,'vscode-intro')

S('Use local VS Code to edit files on the cluster',
  img('vscode-architecture.png','Microsoft Remote - SSH architecture showing the local editor and remote files','Microsoft diagram: the laptop editor connects over SSH to remote project files.','wide-image')+rows([('On your laptop','The VS Code window and its controls'),('On the cluster','The project files and commands from the remote terminal')])+note('Open, edit, and save cluster files directly in the VS Code window.'),
  'The VS Code window runs on the laptop. The project files can live on another computer. Microsoft’s Remote - SSH extension connects the two through SSH, so the editor can open and save the remote files.\n\nThe left side of this diagram is the application we see on the laptop. The right side is the remote system containing the files and the processes used by the remote terminal. The connection joins them without requiring us to download a file, edit it, and upload it again after each change.\n\nThis connection provides access to the files; it does not reserve resources for an analysis. Slurm will handle that later. For now, the useful distinction is between where the window is displayed and where its files and commands are located. The next diagram makes that distinction concrete.',['vscode'],F)

S('Files stay on the cluster; terminal commands run there',
  concept_diagram('local-remote')+note('In the SSH window, saves update cluster files and terminal commands run on the connected host.'),
  'Here, the screen, keyboard, and VS Code application are on the laptop. The file shown in the editor is analysis.py, but its location is demo/analysis.py on the cluster. Saving in this connected window updates that remote file. This diagram shows the state after upload; the next few slides show how to get there.\n\nThe terminal is also displayed in the laptop window, but its commands run on the connected cluster host. Our initial connection reaches a login node. A separate local terminal would run commands on the laptop instead. Later, an interactive job can start a shell on a compute node, so the host running a command matters.\n\nFor file work, the benefit is straightforward: open, edit, and save the remote file directly. Now we can install VS Code and the extension that provides this connection.',['vscode','prog'],F,'concept-slide'),

S('Install VS Code and the Remote - SSH extension',
  rows([('Install VS Code','Download, install, and open the desktop application.'),('Open Extensions','Click the Extensions icon in VS Code’s left sidebar.'),('Search','Enter Remote - SSH; choose the extension published by Microsoft.'),('Install','Click Install for Remote - SSH and wait until installation finishes.')])+'<div class="link-row"><a href="https://code.visualstudio.com/docs/setup/setup-overview" target="_blank">Official VS Code setup ↗</a></div>'+note('This installs the editor and connection tool on your laptop.'),
  'Both installation steps happen on the laptop. First, download the VS Code desktop application for the operating system, install it, and open it. Inside VS Code, the Extensions icon opens the catalogue of add-on features. An extension adds a capability to the editor.\n\nSearch for Remote - SSH and check that Microsoft is listed as the publisher. Install that extension and wait for the installation to finish. It provides the connection commands we will use on the next slide. This prepares the editor on the laptop; Python and analysis packages on the cluster are set up separately.\n\nThe connection commands are found in the Command Palette, which is a searchable menu of VS Code actions. We will open that menu and use the same NetID and cluster hostname that worked in the SSH test.',['vscode_setup','vscode'],F)

S('Connecting VS Code with Remote - SSH',
  rows([('Command Palette','Cmd+Shift+P on macOS; Ctrl+Shift+P on Windows/Linux'),('Choose','Remote-SSH: Connect to Host…'),('Enter and sign in','YOUR_NETID@cc-login.campuscluster.illinois.edu')])+img('vscode-host.png','Microsoft example of the Connect to Host selector','Microsoft example UI. Enter your NetID and the ICC hostname in this field.','host-image')+p('Sign in with password + Duo. Choose Linux if asked. Confirm the lower-left SSH indicator names the cluster.','small'),
  'The Command Palette is VS Code’s searchable action menu. Open it with Command-Shift-P on macOS, or Control-Shift-P on Windows or Linux. Choose Remote-SSH: Connect to Host, then enter the same NetID and cluster hostname used in the terminal test.\n\nComplete the password and Duo prompts. If VS Code asks for the remote operating system, choose Linux because that is what the cluster runs. A connected window may open separately. The SSH indicator in the lower-left corner should identify the cluster host; that is the confirmation that this window is connected remotely.\n\nIf the window seems to be waiting, check the Remote - SSH output or login terminal for an authentication prompt. Once connected, the next decision is where the project files should go. We need to choose the storage location before uploading anything.',
  ['prog','vscode'],
  F,
  'compact')

S('Choose home, project, or scratch storage',
  table(['Location','Use it for','Limits and actions'],[['/u/YOUR_NETID','Settings and small personal files','Very limited quota: 100 GiB (soft limit). Keep large datasets elsewhere.'],['/projects/YOUR_GROUP','Group data, software, and retained outputs','Shared group quota. Keep backups: no snapshots are kept for file recovery.'],['/scratch/YOUR_NETID','Temporary working data','Temporary only: files typically deleted after 30 days without access, sometimes sooner.']])+note('Use your group’s full project path; <code>/projects/YOUR_GROUP</code> is a placeholder.'),
  'These three locations have different purposes. Home, under /u, is for settings and small personal files. A quota is the amount of storage you may use. The documented home quota is 100 GiB soft and 103 GiB hard. The soft limit allows a grace period; staying above it for seven days stops new writes until usage is reduced. Home quota cannot be expanded.\n\nProject storage is shared within the group, and its capacity depends on the group’s allocation. It has no snapshots, meaning saved filesystem states for recovering earlier files. Important data therefore need a separate backup plan.\n\nScratch is temporary working space. Files are typically deleted after 30 days without access, and space pressure can cause earlier deletion. Purged data cannot be recovered, so move valuable outputs elsewhere.\n\nThe displayed project path is a placeholder. Use the full path supplied by your group, where you have permission to save files. We will open that parent folder before uploading demo.',['storage'],F,'storage-slide')

S('Open the remote project location',
  img('vscode-folder.png','Microsoft example of opening a folder over SSH','Microsoft example UI. Replace its sample path with your assigned project location.','folder-image')+rows([('File → Open Folder','Open /projects/YOUR_GROUP or your assigned path.'),('Check the connection','Confirm the lower-left SSH indicator names the cluster.'),('Check Explorer','It should show the group folder that will receive demo.')])+note('The Explorer now shows the remote location, before the upload.'),
  'We have selected the storage area; now we open the destination in VS Code. In the connected window, choose File, then Open Folder. Enter the approved group path. In our example, /projects/YOUR_GROUP is the parent folder that will contain demo.\n\nThe path in Microsoft’s screenshot belongs to its example system, so use the path supplied by your own group. The SSH indicator should still identify the cluster. With that connection active, Explorer displays folders on the remote computer rather than folders on the laptop.\n\nAt this stage, we have only opened a destination. The demo folder is still on the laptop and has not yet been transferred. Keeping those two locations separate avoids uploading to the wrong place. The next step moves the folder into this remote destination.',['vscode'],F,'compact')

S('Upload the demo folder with VS Code',
  rows([('On the laptop','Unzip the offline package; find HPC_Introduction/demo.'),('Upload','Drag demo into the remote Explorer destination.'),('Open the project','File → Open Folder → /projects/YOUR_GROUP/demo'),('Check a file','Open data/samples.csv and look for the three sample rows.')])+note('After upload finishes, open data/samples.csv from the remote Explorer to check it arrived.'),
  'The offline package contains a supplied demo folder with the small input and scripts used in the lecture. After unzipping the package on the laptop, that folder is inside HPC_Introduction. Drag the whole demo folder into the remote Explorer destination, rather than onto an open editor tab.\n\nWait until the transfer finishes. Then use File, Open Folder to open /projects/YOUR_GROUP/demo, replacing the group path with the approved location. Expand data and open samples.csv. Seeing the header and three sample rows confirms that the uploaded file can be read remotely.\n\nChanges saved with Command-S or Control-S now update the remote file directly. This graphical transfer is suitable for these small files. Large datasets should use the group’s recommended transfer service, such as Globus, with completion checked before analysis. Next, we will open a terminal inside this same remote project folder.',['vscode','transfer','storage'],F,'compact')

S('Open a terminal in the same project',
  code('hostname\ncd /projects/YOUR_GROUP/demo\npwd','VS Code → Terminal → New Terminal')+rows([('hostname','Print the host name; expect a login node here.'),('cd','Change to the remote project folder shown in Explorer.'),('pwd','Print the full current folder path.')])+note('Run one line, press Enter, wait for the prompt, then continue.'),
  'The terminal is the text window, and the shell is the program that reads the commands we enter. In the remote VS Code window, Terminal → New Terminal opens a shell on the connected cluster host.\n\nFirst, hostname tells us which computer is running that shell. At this point, we expect a login host, such as cc-login1. Next, cd changes the current folder to our uploaded project. The displayed project path is a placeholder; use the full path assigned by the group. Finally, pwd prints the full current path, so we can check that the terminal and Explorer refer to the same folder. A successful cd usually prints nothing.\n\nThe prompt is the text that appears when the shell is ready for another command. In these transcripts, a dollar sign marks that prompt; it is not part of the command to type. Short file checks can run here on the login node. We will submit the analysis to compute resources later. First, let us see how to read a command.',['shell'],C)

S('Read the program, options, and path in a command',
  '<div class="hero-code"><span class="accent">head</span> <span class="teal">-n 5</span> <span class="gold">data/samples.csv</span></div>'+rows([('Program','head displays the beginning of a text file.'),('Option + value','-n 5 asks for the first five lines.'),('File path','data/samples.csv is the path to the file to read.')])+note('Quotes keep a path together: <code>head -n 5 "data/samples.csv"</code>. They are required for paths containing spaces.'),
  'This command has three parts. head is the program. The option -n, followed by the value 5, asks for the first five lines. data/samples.csv is the path to the file we want to read. If the file contains fewer than five lines, head prints only the lines that exist.\n\nEverything after the program name is an argument. Some arguments are options that change the program’s behavior; others supply values or file paths. The same option letter can mean something different in another program, so its meaning belongs to that command.\n\nSpaces normally separate arguments. Quotes keep a path containing spaces together as one argument. The quoted example here works too, although this particular path has no spaces and does not need quotes. We can use this same reading pattern for file commands and Slurm settings. Next, we will look at how the current folder affects a file path.',['shell','cli'],C)

S('Navigate the uploaded project',
  cols(transcript('$ pwd\n/projects/YOUR_GROUP/demo\n$ cd data\n$ pwd\n/projects/YOUR_GROUP/demo/data\n$ cd ..\n$ pwd\n/projects/YOUR_GROUP/demo\n$ cd ~\n$ pwd\n/u/YOUR_NETID\n$ cd -\n/projects/YOUR_GROUP/demo\n$ pwd\n/projects/YOUR_GROUP/demo','Transcript: type commands after $; other lines are output'),table(['Command','Meaning'],[['pwd','Print the current folder'],['cd data','Enter the data subfolder'],['cd ..','Go up one folder'],['cd ~','Go to your home folder'],['cd -','Return to the previous folder']])+p('<code>cd -</code> also prints its destination. The next <code>pwd</code> confirms it.','small'))+p('<code>.</code> current folder · <code>..</code> parent · <code>/projects/…</code> absolute path · <code>data/…</code> relative path','small'),
  'pwd shows that our starting folder is demo. cd data enters its data subfolder, and the next pwd confirms the full path. cd .. moves up one level, back to demo. The two dots mean the parent folder.\n\ncd ~ takes us to our home folder, shown here as /u/YOUR_NETID. cd - then returns to the previous folder, which is demo in this sequence. Previous folder and parent folder are different ideas. Unlike the other cd commands shown here, cd - also prints its destination, so that path appears again when we run pwd.\n\nAn absolute path starts with a slash and gives the location from the filesystem root. A relative path, such as data, starts from the current folder. A single dot means the current folder, and a tilde means home. File and folder names are case-sensitive.\n\nThe dollar-prefixed lines are commands; the other lines are example output. The final pwd confirms that we are back in demo. From there, we can list the data folder without entering it.',['shell'],C,'compact navigation-examples')

S('List files and inspect their details',
  cols(table(['Command','What changes'],[['ls','List visible file and folder names'],['ls -a','Include hidden names beginning with a dot'],['ls -l','Show details such as size and date'],['ls -lh','Use readable sizes, such as K or M'],['ls -lah','Show hidden names, details, and readable sizes']]),transcript('$ ls data\nsamples.csv\n$ ls -a data\n.  ..  samples.csv\n$ ls -l data\n-rw-r--r-- 1 user group 58 Oct 27 10:00 samples.csv\n$ ls -lh data\n-rw-r--r-- 1 user group 58 Oct 27 10:00 samples.csv\n$ ls -lah data\ndrwxr-xr-x 2 user group 4.0K Oct 27 10:00 .\ndrwxr-xr-x 3 user group 4.0K Oct 27 10:00 ..\n-rw-r--r-- 1 user group   58 Oct 27 10:00 samples.csv','Illustrative listing lines; total lines omitted'))+p('The CSV is only <strong>58 bytes</strong>, so <code>-h</code> still shows 58. Later, <code>ls -a</code> will reveal the <code>.venv</code> folder we create.','small'),
  'All five commands list the same data folder. ls shows its visible file names without changing our current folder. Adding -a also shows names beginning with a dot, including the current-folder entry, dot, and the parent-folder entry, double dot.\n\nThe -l option adds details. A file’s line shows permissions, link count, owner, group, size, modification time, and name. We mainly need the name and size here. The displayed users, dates, and directory sizes are examples; a real listing will differ.\n\nAdding -h makes larger sizes easier to read, using units such as K and M. This CSV is only 58 bytes, so it still appears as 58. The combined form -lah shows hidden entries, details, and readable sizes together. The directory entry’s size is not the total size of everything inside it; we will use du for that later.\n\nAfter Python setup, ls -a in demo will also reveal the hidden .venv folder. For now, we have found the input file and can create a folder for outputs.',['shell','cli'],C,'compact listing-examples')

S('Creating, copying, moving, and deleting',
  table(['Command','Result'],[['<code>mkdir results</code>','Create one new folder'],['<code>mkdir -p results/qc</code>','Create missing folders along the path; accept existing folders'],['<code>cp -i notes.txt notes_backup.txt</code>','Copy a file; ask before overwriting'],['<code>cp -r data data_backup</code>','Copy the folder and all its subfolders to a new location'],['<code>mv -i notes_backup.txt notes_old.txt</code>','Rename or move; ask before overwriting'],['<code>rm -i notes_old.txt</code>','Ask before deleting this file']])+p('<code>cp</code> and <code>mv</code>: source first, destination second. Shell deletion normally has no Trash recovery.','small'),
  'These commands manage files and folders; the same basic actions are also available in VS Code Explorer. mkdir results creates one folder. If that folder already exists, plain mkdir reports an error. mkdir -p results/qc creates any missing folders along that path and accepts folders that already exist.\n\nFor cp and mv, the source comes first and the destination second. cp creates a copy, while mv moves or renames the original. The -i option asks before replacing an existing destination. cp -r copies a folder and its subfolders. In this example, data_backup is a new destination; copying large research data would also use additional storage.\n\nrm -i asks before deleting notes_old.txt. The shell normally does not send deleted files to a Trash folder, so the filename matters before confirming removal. These commands often print nothing when they succeed. ls lets us check the resulting names. With the folder structure in place, we can inspect the contents of a text file.',['shell','script'],C,'compact')

S('Inspecting a small text file',
  cols(table(['Command','Use'],[['<code>cat notes.txt</code>','Print the entire small file'],['<code>head -n 5 data/samples.csv</code>','Print up to 5 lines from the start'],['<code>less notes.txt</code>','Browse text; press q to leave']]),code('sample_id,reads\nsample_A,1000\nsample_B,1500\nsample_C,1200','Output of head for the included sample table'))+note('Preview a few rows before running the analysis. Avoid printing a huge file with <code>cat</code>.'),
  'cat prints an entire text file into the terminal. That is convenient for a short note or configuration file, but a large file can flood the display. head gives us a smaller preview. Here, -n 5 asks for up to five lines from the start.\n\nThe CSV contains only four lines, so all four appear. The first line names the columns, and commas separate the fields. The remaining lines contain sample names and example values.\n\nless opens a text viewer that we can scroll through. Pressing q closes the viewer and returns to the shell. These commands are for ordinary text; images, saved R objects, and other binary formats need an appropriate viewer. We can also open these small files in VS Code. Next, we will distinguish searching for a filename from searching inside a file.',['shell','cli'],C,'compact')

S('Find a file, then find text inside it',
  code('find data -type f -name "*.csv"','Search filenames within data and its subfolders')+rows([('-type f / -name','Keep files only / match their names against the pattern.'),('"*.csv"','The * matches any text before .csv.')])+code('grep -n "sample_B" data/samples.csv','Search inside this file; -n includes line numbers')+code('3:sample_B,1500','Expected grep output: line 3 contains the match'),
  'find searches for files under a starting folder. Here, data is the starting location. The option -type f keeps regular files in the results, and -name tests their names against a pattern. The star in "*.csv" matches any sequence of characters before .csv. The quotes pass that pattern to find without the shell expanding it first. In this small folder, the expected result is data/samples.csv.\n\ngrep answers a different question: does the file’s text contain the pattern we supply? Here, it looks for sample_B inside samples.csv. The -n option includes line numbers. The result 3:sample_B,1500 means the matching text is on line three.\n\nNeither command changes the file. Searching within the relevant project folder keeps the output useful. We can then count lines and check how much storage the folder uses.',['script','cli'],C,'compact')

S('Count lines and check disk usage',
  cols(code('wc -l data/samples.csv','Run this command')+code('4 data/samples.csv','Expected output; do not type this line'),rows([('wc -l','Count lines in this text file.'),('4 lines','One header plus three sample rows.')]))+code('du -sh data','Check space used by the input folder')+p('<code>-s</code> gives one summary total · <code>-h</code> uses readable units such as K or M','small')+note('<code>wc -l</code> includes header lines. <code>du</code> shows space used; <code>quota</code> shows usage and limits.'),
  'wc -l counts the lines in a text file. For this CSV, the result is four: one header line and three sample rows. The filename after the number identifies the file that was counted. These four lines all end with a newline; that is what wc -l counts.\n\nA line count is not automatically a sample count. Other file formats may include comments, extra headers, or records that span several lines, so we need to understand the format before interpreting the number.\n\ndu reports space used on disk. The -s option gives one total for the folder, and -h uses readable units such as K or M. The value can vary with the filesystem. It tells us how much space this folder uses. To check the storage allowance as well, quota reports usage and limits for the filesystem areas we can access. Next, we will see how to look up unfamiliar command options.',['cli','storage'],C,'compact')

S('Help and everyday terminal shortcuts',
  table(['Command / key','What it does'],[['<code>man ls</code>','Open the manual; press q to leave'],['<code>head --help</code>','Show the Linux command’s built-in help'],['Tab','Complete a file or folder name'],['↑ / <code>history</code>','Recall previous commands / list shell history'],['Ctrl+C','Interrupt the command currently running in this terminal'],['<code>clear</code> / <code>exit</code>','Clear the display / leave the current shell']])+p('Keep this login shell open for job submission; exit closes it.','small'),
  'There is no need to memorize every option. man ls opens the manual for ls, and q closes that viewer. Many programs also provide help through --help, as head does here. Options can differ between a laptop’s tools and the Linux tools on the cluster, so these examples refer to the remote Linux shell.\n\nTab completes file and folder names. The up arrow recalls a previous command so we can inspect or edit it before running it again. history lists earlier commands.\n\nCtrl+C interrupts the command currently occupying the terminal. It does not cancel a job that was separately submitted through Slurm. clear clears the visible display, while exit leaves the current shell. Depending on where we are, exit can close an interactive allocation or the SSH connection. Here we keep the login shell open. We now have the basic commands needed to prepare and submit a job.',['shell','cli'],C,'compact')

S('Slurm runs work on allocated resources',
  concept_diagram('login-compute')+p('<strong>Batch:</strong> submit a script. <strong>Interactive:</strong> request a compute shell with <code>srun</code>.','small')+note('Submit on the login node; the job runs on an allocated compute node.'),
  'We prepare and submit a batch job from the login node. Slurm is the scheduling software that handles the request. It may hold the job in a queue until the requested CPUs, memory, and other resources are available. Allocating resources means reserving them for the job. The program then runs on a compute node.\n\nThe two nodes can access the same approved project folder. The job reads the inputs and writes its output there, so we do not need to copy the whole project to a different computer for each submission. Slurm is software, not an extra storage location between the two nodes.\n\nAfter sbatch submits a batch script, our terminal remains on the login node. The job can continue after the laptop disconnects. An interactive job instead gives us a shell on allocated compute resources, which we will use later for software setup. First, we will read the small hello.sbatch file to see what a batch request contains.',['jobs','sbatch','srun'],J,'concept-slide'),

S('Read a Slurm batch script line by line',
  annotated(BATCH)+p('Edit these lines inside hello.sbatch in VS Code, then save. Submit it from the terminal after reviewing the resource settings.','small'),
  'hello.sbatch is a plain text file containing resource requests and commands. Its first line selects Bash, the shell that will read the commands. Lines beginning with #SBATCH are instructions for Slurm, and they must come before the commands that run the program.\n\nThe job name helps us recognize the submission. The account and partition must be a valid pair for our group: the account identifies the compute allocation, and the partition selects a queue we can use. The remaining requests specify nodes, tasks, CPUs per task, memory, and a maximum running time. The final echo command prints one message.\n\nWe edit and save this file in VS Code, then submit it with sbatch. Running bash hello.sbatch directly would run the command on the current machine and treat the #SBATCH lines as comments; it would not request compute resources. The five-minute limit applies after the job starts, not while it waits in the queue. Before submitting, let us clarify how nodes, tasks, and CPUs fit together.',['sbatch'],J,'beginner-script')

S('Set nodes, tasks, CPUs, memory, and time for a job',
  p('Example resource request: count the node, the tasks, then the CPUs.','small')+concept_diagram('resource-hierarchy')+p('Reserving resources does not launch the tasks or make the program parallel.','small')+'<div class="resource-demo"><strong>Keep hello.sbatch at: 1 node · 1 task · 1 CPU/task</strong><div><code>--mem=1G</code><span>1 GiB of RAM per node</span><code>--time=00:05:00</code><span>Runtime limit: hours:minutes:seconds</span></div></div>',
  'The diagram is a resource-counting example. One node means one computer. The two task boxes represent two program processes across the whole job. Each task has two CPUs reserved, so the request is two tasks times two CPUs per task: four CPUs in total. ntasks already counts tasks across all nodes; we do not multiply by the node count again.\n\nA task is not a sample or a file. These boxes represent resources requested for the program, not every CPU physically installed in the node. A Slurm CPU may be a core or a hardware thread, depending on the system.\n\nRequesting resources does not automatically make a program use them. A plain python analysis.py command starts one process. Multiple processes need a suitable launcher and program, and a multithreaded program needs its own worker or thread setting.\n\nOur actual hello script keeps the smaller settings shown below: one node, one task, and one CPU. --mem=1G asks for one GiB of RAM per node, not disk space. --time=00:05:00 limits running time to five minutes and excludes queue waiting. Real analyses need requests based on their software and data. We can now submit the saved hello file.',['sbatch'],J,'concept-slide resource-slide')

S('Submit the first job: hello.sbatch',
  code('pwd\nls hello.sbatch\nsbatch hello.sbatch','In the remote demo folder, after saving the file')+code('Submitted batch job 123456','Example response; record the ID returned by your submission')+note('This first job prints a message. It does not run analysis.py yet.'),
  'The file is ready once the account and partition placeholders have been replaced with the valid values for our group and the remote file has been saved. In the terminal, pwd confirms that we are in the project folder, and ls hello.sbatch confirms that the script is present there.\n\nsbatch hello.sbatch sends that saved file to Slurm. A successful submission returns a job ID. The number 123456 on this slide is an example; the ID from the actual response is the one to keep for status checks, log filenames, and cancellation.\n\nSubmitting a job does not mean it has started or finished. It may wait for resources. Saving the file or pressing the editor’s Run button does not perform this Slurm submission. This first job only prints a short message, so it checks the submission process before we add analysis software. Next, we will see how to check its queue status.',['sbatch'],J)

S('Checking the queue and stopping a job',
  code('squeue -u YOUR_NETID','-u selects your user; run squeue again to refresh the snapshot')+table(['State','Meaning'],[['PD','Pending: queued; check the listing for the reason'],['R','Running: the job is using its assigned resources']])+code('scancel 123456','Only for an unwanted job; let hello finish in this example')+p('After hello leaves the queue: <code>cat slurm-123456.out</code> → <strong>My first HPC job</strong>. Use your job ID.','small'),
  'squeue lists jobs that are queued or running. The -u option limits the listing to the NetID we provide. Each call shows a snapshot, so running it again gives a fresh view. PD means pending: the job is queued, and the listing provides a reason. R means running. A small job may finish before we look at the queue.\n\nscancel followed by a job ID stops that job. This is an option for an unwanted or incorrect submission; we would let the hello job finish so we can read its message. Ctrl+C in a log viewer does not cancel a batch job.\n\nAfter hello leaves the queue, cat opens its default output file in the submission folder. We replace 123456 with the actual ID. The expected message is My first HPC job. Leaving the queue alone does not prove success; missing output or an error needs investigation. Next, we can choose clearer log filenames and optional email notifications for an analysis job.',['jobs','states'],J,'compact')

S('Output files and email notifications', '<div class="code-label">In analysis.sbatch, before executable commands</div><pre class=""><code>#SBATCH --output=analysis-%j.out\n#SBATCH --error=analysis-%j.err\n#SBATCH --mail-type=END,FAIL\n#SBATCH --mail-user=YOUR_NETID@illinois.edu</code></pre><table class=""><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>--output / --error</td><td>Files for program output / error and diagnostic messages</td></tr><tr><td>%j</td><td>Slurm inserts the job ID: analysis-123457.out</td></tr><tr><td>--mail-type=END,FAIL</td><td>Ask for notification at job end or failure</td></tr><tr><td>--mail-user</td><td>The recipient; use your address or remove both mail lines</td></tr></tbody></table>', 'These directives are already included in the supplied analysis.sbatch template. They belong before the commands that load software and run the analysis. --output names the file for ordinary program output, and --error names the file for error and diagnostic messages. A program may send normal progress information to the error stream, so a nonempty .err file does not by itself mean failure.\n\nSlurm replaces %j with the job ID automatically. For job 123457, analysis-%j.out becomes analysis-123457.out. We leave %j in the script rather than replacing it ourselves. With these plain filenames, logs appear in the submission folder. A log subfolder would need to exist before submission.\n\n--mail-type selects email events: END for job end and FAIL for failure. --mail-user sets the recipient. We replace the address or remove both mail lines. Delivery depends on the cluster’s email configuration, and a completion email does not validate the result. The next two pages cover optional GPU and named-node requests.', ['sbatch'], J, 'compact')

S('When the analysis needs a GPU',
  code('#SBATCH --partition=YOUR_GPU_PARTITION\n#SBATCH --gres=gpu:GPU_TYPE:1','Optional GPU job: use your group’s GPU partition and GPU type')+code('nvidia-smi','Inside an allocated NVIDIA GPU job')+rows([('--gres','Request GPUs with gpu:TYPE:COUNT; count is per node.'),('GPU_TYPE / final 1','The configured GPU type / one GPU per allocated node.')])+note('The tiny demo needs no GPU. Add this only for software that supports and uses one.'),
  'A GPU is an additional processor used by software that supports GPU computing. The request needs a GPU partition and account that our group can access. In --gres=gpu:GPU_TYPE:1, gpu identifies the resource, GPU_TYPE is a type name configured on the cluster, and the final 1 asks for one GPU per allocated node. The group’s documentation or support contact can confirm the valid names.\n\nRequesting a GPU does not make CPU-only software use it. Inside an allocated NVIDIA GPU job, nvidia-smi shows the GPU that is visible to the job and basic usage information. GPU memory is separate from the CPU RAM requested with --mem.\n\nThe analysis software also needs an environment compatible with that GPU; its installation instructions specify those requirements. The tiny example here stays on CPUs. A related optional request is choosing a particular compute node, which is different from choosing a GPU type.',['jobs','sbatch'],J)

S('When a particular node is required',
  code('#SBATCH --nodes=1\n#SBATCH --nodelist=NODE_NAME','Optional: use a compute-node name your account can access')+code('sinfo -p YOUR_PARTITION -N','sinfo: inspect resources; -p selects the partition; -N lists nodes')+rows([('--nodes=1','How many nodes you request'),('--nodelist','Which named node you request')])+note('Normally let Slurm choose. Name a compute node only when your group requires that machine.'),
  '--nodes and --nodelist answer different questions. --nodes=1 asks for one computer. --nodelist=NODE_NAME asks for a particular named computer. NODE_NAME must be replaced by a real compute-node name in a partition that our account can use; a login-node name does not belong here.\n\nsinfo shows cluster resources. In this command, -p selects the partition, and -N displays information by node. Seeing a node in the output does not grant permission to use it.\n\nMost jobs can let Slurm choose any node that satisfies the resource request. Choosing one particular machine narrows the choice and may increase waiting. It can be useful when a group requires that machine for a hardware-specific test or comparison. If the real need is simply more memory or a GPU type, requesting that resource may be enough. Next, we will request an interactive compute shell to prepare software.',['sbatch','jobs'],J)

S('Open an interactive compute shell with srun',
  code('srun --account=YOUR_ACCOUNT --partition=YOUR_PARTITION \\\n  --nodes=1 --ntasks=1 --cpus-per-task=2 \\\n  --mem=4G --time=00:15:00 --pty bash','From the login shell in demo: paste this whole block as one command')+rows([('srun','Start a program on allocated compute resources.'),('--pty bash','Open an interactive terminal running the Bash shell.'),('After the prompt returns','hostname should show a compute node; pwd should show the project folder.')])+p('A trailing <code>\\</code> continues a command onto the next line; nothing follows it on that line.','small'),
  'We have used the login node to manage files and submit jobs. Software setup may also need compute resources, so this command opens a shell on a compute node. It requests two CPUs, four GiB of memory, and fifteen minutes. These are example resources for a small setup task, not requirements for every installation. YOUR_ACCOUNT and YOUR_PARTITION must be replaced with the approved values.\n\nThe backslashes join the displayed lines into one command. Each backslash must be the last character on its line. srun requests resources and starts a program; --pty bash gives us an interactive Bash shell on those resources.\n\nThe request may wait in the queue. When the prompt appears, hostname should identify a compute node, and pwd should show the project folder. This shell is where we will prepare Python. Opening it does not move VS Code’s Run button or notebook execution onto the compute node.',['jobs','srun'],J,'compact')

S('Make Python available in the compute shell',
  code('module avail python\nmodule load python/3.11.11\nmodule list','Inside the allocation, in demo; use a version shown as available')+table(['Command','Meaning'],[['module avail python','List cluster modules matching Python'],['module load python/3.11.11','Select this installed Python version for this shell'],['module list','Confirm which cluster modules are loaded']])+note('analysis.py needs pandas. Next, create .venv in demo and install pandas there.'),
  'We are still in the compute shell, inside the remote demo folder. The cluster already provides software installations, and the module command selects which one this shell uses. module avail python lists matching choices. module load python/3.11.11 selects the illustrated version, and module list shows what is loaded. The part after the slash is the version number. Use a version that is actually listed, and use that same version in the later batch script.\n\nSelecting Python does not install every Python package. A package is reusable code that an analysis can import. Our analysis.py imports pandas to read a table, so pandas must also be available to this Python installation.\n\nNext we will create a Python environment in the project folder and install pandas there. This cluster module command and Python’s -m option are different tools, despite the similar wording.',['software'],P)

S('Create a Python environment and install pandas',
  code('python -m venv .venv\nsource .venv/bin/activate\npython -m pip install pandas\nls -a','Continue in the same compute shell and remote demo folder')+rows([('Create .venv','-m runs Python’s venv utility; .venv is the new folder.'),('Activate','source makes this shell use .venv/bin/python.'),('Install pandas','-m pip runs the package installer for the selected Python.')])+p('Wait for pip to finish and the prompt to return. Then check the import on the next slide.','small'),
  'The first command creates a Python environment in a folder named .venv. An environment gives this project its own Python package installation. In python -m venv, -m asks Python to run its venv tool, and .venv names the destination folder.\n\nThe source command activates that environment in the current shell. After activation, the python command selects .venv/bin/python. It does not download packages. The next line runs pip, the Python package installer, with that selected Python and asks it to install pandas.\n\nInstallation takes time, so we wait for it to finish and for the command prompt to return. ls -a includes hidden names and now shows .venv. Those files are on the cluster, inside the project folder; a laptop environment should not be copied here.\n\nActivation applies to this shell. A later shell or batch job must select the environment again. Before leaving this shell, we will check that pandas really imports.',['python','python_cli','software'],P,'compact')

S('Check that pandas imports and save package versions',
  code('python -c "import pandas; print(pandas.__version__)"','-c executes the quoted Python code immediately')+rows([('import pandas','Check that this Python can load the package.'),('Print version','print(pandas.__version__) displays the installed version; expect a version number.')])+code('python -m pip freeze > requirements.txt','freeze lists installed package versions; > writes them into this file')+note('Continue when a version prints without an error. Keep this compute shell open.'),
  'This check uses the environment that is already active. Python’s -c option executes the code between the quotation marks. The first statement imports pandas, and the second prints its version. The semicolon separates those two statements. __version__ is the package’s stored version information.\n\nThe expected outcome is a version number with no import error. The exact number may differ between installations. If the import fails, load the chosen Python module, activate .venv again, and confirm that installation finished without errors before retrying. A completed download alone does not prove the package is usable.\n\nThe second command records the installed package versions. pip freeze lists them, and the greater-than sign writes that list into requirements.txt, replacing that file if it already exists. This creates a record; it does not install anything again.\n\nWe now have installed package files and an active shell. The next diagram separates those two things.',['python','python_cli','software'],P,'compact')

S('The environment stays; activation is per shell',
  concept_diagram('install-activate')+note('After setup, <code>exit</code> returns to the login shell; .venv stays in project storage.'),
  'Installation and activation do different jobs. In the top row, pip writes pandas and its dependencies into .venv. The folder is stored with the project and remains after the compute shell closes.\n\nIn the bottom row, activation makes the current shell choose .venv/bin/python. It selects existing files; it does not reinstall them or request compute resources. A later batch job loads the same compatible Python module and activates that same folder again. Activation in this shell does not automatically prepare a separate terminal or job.\n\nImporting is another step: import pandas loads the installed package into a running Python program.\n\nSetup is now complete. exit leaves the compute shell and releases this interactive allocation. hostname and pwd confirm that we are back on the login node in the project folder. If the allocation has already ended, check the host before typing exit again.\n\nThe next page shows Conda as an alternative setup route. The Python environment we just prepared is already ready for its batch job.',['python','radmin'],P,'concept-slide'),

S('Create a Conda environment from a supplied file',
  code('module avail miniconda3\nmodule load YOUR_CONDA_MODULE\nconda env create -f environment.yml\nconda run -n analysis python -c "import pandas; print(pandas.__version__)"','Alternative route when the project supplies environment.yml')+rows([('environment.yml','Records the environment name and requested packages'),('-f environment.yml','Read the environment specification from this file.'),('-n analysis','Use the environment named analysis (from name: analysis in the file).')])+p('Choose this instead of .venv. In a new compute shell, expect a pandas version with no error.','small'),
  'Some projects provide environment.yml instead of instructions for creating .venv. That file describes a Conda environment: its name and the packages to install. This is an alternative route, not an additional setup step for the Python example.\n\nThe supplied file is in examples, so it must be copied into the remote project before this command can read it. Setup takes place in a new compute shell. Conda may use home space, so run quota first. If home is nearly full, ask the group’s technical contact where to create the environment before proceeding. module avail miniconda3 helps identify an available Conda module; YOUR_CONDA_MODULE is replaced with its actual name.\n\nconda env create builds the environment, and -f selects the file to read. Here the file names the environment analysis. conda run -n analysis executes a command in that environment, and the final Python code checks pandas and prints its version. Continue only when that check finishes without an error.\n\nAfter the import check, exit the setup shell. We now return to the prepared .venv route and put its software setup into a batch script.',['conda','software'],P)

S('Prepare a Python batch job with its environment',
  cols(code('#!/bin/bash\n#SBATCH --job-name=analysis\n#SBATCH --account=YOUR_ACCOUNT\n#SBATCH --partition=YOUR_PARTITION\n#SBATCH --nodes=1\n#SBATCH --ntasks=1\n#SBATCH --cpus-per-task=1\n#SBATCH --mem=1G\n#SBATCH --time=00:05:00','1 · Beginning of analysis.sbatch'),code('#SBATCH --output=analysis-%j.out\n#SBATCH --error=analysis-%j.err\n\nset -e\nmodule load python/3.11.11\nsource .venv/bin/activate\npython analysis.py','2 · Continue in the same file, after the left column'))+note('set -e stops on setup failure. Set your account and partition, then save analysis.sbatch.'),
  'These two columns are consecutive parts of one file: the left column comes first, then the right. All #SBATCH settings appear before the executable commands. The example requests one node, one task, one CPU, one GiB of memory, and five minutes. A real analysis needs resources chosen for its own software and data.\n\nThe output and error settings name the job’s two logs. Slurm replaces %j with the job ID and writes these files in the submission folder. The downloadable template also includes email settings; replace the address or remove both email lines.\n\nBelow the settings, set -e stops this script if a setup command fails. The job loads the same Python module used during setup and activates the existing .venv folder. It then runs analysis.py. Installation is not repeated here.\n\nSet the approved account and partition, use the same Python module as in setup, and save analysis.sbatch in VS Code. The next step sends this saved file to Slurm.',['software','sbatch','python'],R,'compact')

S('Submit the analysis job',
  code('pwd\nls data/samples.csv analysis.py analysis.sbatch\nsbatch analysis.sbatch','In the login shell, from the demo folder')+code('Submitted batch job 123457','Illustrative analysis job ID; hello used 123456')+code('squeue -u YOUR_NETID','Check whether this new job is pending or running')+note('Use the returned ID in analysis-JOBID.out and analysis-JOBID.err.'),
  'The input file, Python script, batch file, and installed environment are now ready. We submit from the login shell, with the terminal in the remote demo folder. pwd confirms that folder. The ls command checks that the three named files can be found before sbatch submits the job file.\n\nSubmitted batch job 123457 is an example response. In an actual session, the returned number identifies that submission. It is different from the earlier hello job’s number, so the two sets of logs must not be mixed up.\n\nsqueue -u YOUR_NETID shows the jobs belonging to that user. PD means the job is waiting; R means it is running. With these output settings, the logs will be analysis-JOBID.out and analysis-JOBID.err, using the returned number. They may not appear until execution begins.\n\nOnce the log exists, we can read it while the program runs.',['sbatch','jobs'],R)

S('Watch job output and search the error log',
  code('tail -n 20 analysis-123457.out\ntail -f analysis-123457.out','After the analysis job starts and the log exists')+code('grep -in "error" analysis-123457.err','First press Ctrl+C to stop tail; then search the error log')+rows([('Ctrl+C','Stop tail; the submitted job keeps running.'),('Need to cancel?','scancel 123457 cancels this analysis job.')])+note('tail: -n 20 = last 20 lines, -f = follow new output · grep: -i = ignore case, -n = line numbers'),
  'The two tail commands answer different questions. tail -n 20 shows the last twenty lines and then returns to the prompt. tail -f keeps watching the file and displays new output as it is written. The filename must contain the current job’s ID.\n\nWhile tail -f is active, this terminal is occupied by the viewer. Ctrl+C stops that viewer and returns to the prompt; the batch job continues. Cancelling the job requires scancel with its job ID.\n\nAfter leaving tail, grep searches the error log. In -in, i ignores letter case and n adds line numbers, so we can locate matching messages. A match needs interpretation, and no match does not prove success. Programs may write ordinary status messages to the error stream, so a nonempty .err file is not automatically a failure.\n\nLogs help explain what happened. Next we will also open the actual output file and check what the analysis produced.',['shell','cli','jobs'],R,'compact')

S('Open the result in VS Code',
  rows([('Explorer → results','Open an output table; check its column names and sample count.'),('Keep it remote','Read or edit the file without downloading it first.'),('Need a local copy?','Right-click summary.csv and choose Download…')])+table(['Other output types','Viewer'],[['Logs / PNG / JPEG','Built-in text or image viewer'],['CSV / TSV','Text editor; Rainbow CSV adds column colors'],['PDF / notebooks','A PDF viewer extension / Microsoft Jupyter viewer']]),
  'The output can be inspected in the same VS Code window used to upload the project. In Explorer, refresh the folder if necessary, expand results, and open the output file. For a table, useful checks include whether the expected columns are present and whether the sample count matches the input. An empty or incomplete file needs investigation in the logs.\n\nReading this file does not require downloading it. If a local copy is needed, the Explorer Download command copies it to the laptop.\n\nDifferent outputs use different viewers. Text and image files open directly. Rainbow CSV can make table columns easier to distinguish; PDF and notebook files use suitable extensions. Follow the installation prompt for the local or SSH environment. Viewing a notebook does not reserve compute resources or mean its cells are safe to run on the login node.\n\nThe same submission and output-reading routine also works for an R script.',['vscode','csv','pdf','jupyter','transfer'],R,'compact')

S('Run an R script as a Slurm batch job',
  code('module load R\nRscript analysis.R','R commands below the #SBATCH resource settings')+code('sbatch analysis_R.sbatch','Copy analysis.R and analysis_R.sbatch into the project; set the account and partition')+rows([('Same input','data/samples.csv'),('R output','results/summary_R.csv')])+note('This example uses base R; no additional package installation is needed.'),
  'An R project uses the same Slurm submission process. The main difference is the software setup and the command that runs the script. The examples folder includes analysis.R and analysis_R.sbatch. They can be copied into the remote project alongside data/samples.csv, and the job file needs the approved account and partition.\n\nInside the batch job, module load R selects the cluster’s R installation. Use an R module name that is available on the system. Rscript analysis.R then runs the saved script without opening an interactive R console.\n\nThis small script uses only functions included with R, so it needs no extra package installation or custom package library. Its result is results/summary_R.csv. An R workflow that uses additional packages would need those prepared beforehand.\n\nAfter sbatch returns a job ID, use that ID to check the queue and logs, then open the output. The next page connects common error messages with the first thing to inspect.',['software','sbatch'],R,'compact')

S('Common errors and the first useful check',
  table(['What you see','Check first'],[['No such file or directory','Run pwd; check the path and filename capitalization.'],['Command not found','Check spelling; load the module or activate the environment.'],['No module named… / no package called…','Select the intended Python/R environment; install the missing package there.'],['OUT_OF_MEMORY / TIMEOUT','Compare --mem / --time with the tool’s documented requirements.'],['Invalid account / partition','Use your approved --account and matching --partition.'],['Permission denied / quota exceeded','Run quota; confirm the group gave you write access to that folder.']]),
  'An error message gives us a starting point. Repeating the same submission without changing anything usually repeats the problem.\n\nFor a missing file, check the working folder, the path, and capitalization. For a missing command, check its spelling and whether the required software module or environment is selected. A missing Python or R package must be installed in the environment the job actually uses.\n\nOUT_OF_MEMORY means the job exceeded its memory allowance; TIMEOUT means it reached its time limit. Compare --mem and --time in the job file with the error log and the software’s documented requirements before changing them. An invalid account or partition needs the approved allocation and queue pairing. For a quota error, run quota to see usage and limits. For Permission denied, confirm with the group that you have write access to the target folder.\n\nWhen asking for help, include the job ID, batch script, exact error, and software version. These details let the lab contact or ICC support reproduce the context without needing passwords or a large dataset.',['jobs','software','storage'],R,'compact')

S('Documentation and help',
  '<div class="source-columns">'+''.join(f'<div><a href="{SOURCES[k][1]}" target="_blank">{E(SOURCES[k][0])}</a></div>' for k in ['access','jobs','storage','software','shell','cli','vscode','sbatch','python','bioc','conda','reveal'])+'</div>'+p('ICC support: <strong>help@campuscluster.illinois.edu</strong><br>Full references and image credits are in SOURCES.md.','small'),
  'These links provide the next level of detail when a real project needs it. The ICC guide is the starting point for account access, storage rules, available software, and job submission on this cluster. Missing Semester explains the shell concepts behind the commands. The Microsoft and software documentation covers the editor, package environments, and individual command options.\n\nFor an account-specific problem, ICC support can check the details that a general tutorial cannot. Include the job ID and exact error, together with the relevant job file and software version.\n\nWe have now covered the basic workflow: connect, choose a project folder, prepare the software, request resources, submit the script, and inspect the logs and output. The included commands are small teaching examples. For an actual analysis, replace the placeholders and choose resources and software versions that match the project.',[],R)
